import java.util.*;
import java.io.*;
import java.math.BigInteger;

public class FFT {
    private static final int SIZE = 1 << 20;
    private static final long MOD = 998244353L;
    private static final long ROOT = 646L;
    private static final long[] ROOT_POWERS = new long[SIZE];
    private static final long[] ROOT_INV_POWERS = new long[SIZE];
    private static final long SIZE_INVERSE;

    static {
        BigInteger modBI = BigInteger.valueOf(MOD);
        BigInteger rootBI = BigInteger.valueOf(ROOT);
        BigInteger sizeBI = BigInteger.valueOf(SIZE);
        ROOT_POWERS[0] = 1;
        ROOT_INV_POWERS[0] = 1;
        for (int i = 1; i < SIZE; i++) {
            ROOT_POWERS[i] = ROOT_POWERS[i - 1] * ROOT % MOD;
            ROOT_INV_POWERS[i] = ROOT_INV_POWERS[i - 1] * ROOT % MOD;
        }
        SIZE_INVERSE = sizeBI.modInverse(modBI).longValue();
    }

    private BufferedReader consoleInput;
    private PrintWriter consoleOutput;
    private boolean isConsoleMode = true;

    static class CoefficientArray {
        final long[] values = new long[SIZE];

        CoefficientArray(long[] input) {
            for (int i = 0; i < input.length; i++) {
                values[i] = input[i];
            }
        }

        long[] transform(boolean forward) {
            return recursiveTransform(0, 1, forward);
        }

        private long[] recursiveTransform(int start, int step, boolean forward) {
            if (step == SIZE) {
                return new long[]{values[start]};
            }
            long[] even = recursiveTransform(start, step << 1, forward);
            long[] odd = recursiveTransform(start + step, step << 1, forward);
            int half = even.length;
            long[] combined = new long[half << 1];
            for (int i = 0; i < half; i++) {
                long twiddle = forward ? ROOT_POWERS[i * step] : ROOT_INV_POWERS[i * step];
                combined[i] = (even[i] + twiddle * odd[i]) % MOD;
            }
            for (int i = 0; i < half; i++) {
                long twiddle = forward ? ROOT_POWERS[i * step] : ROOT_INV_POWERS[i * step];
                combined[half + i] = ((even[i] - twiddle * odd[i]) % MOD + MOD) % MOD;
            }
            return combined;
        }
    }

    long[] directFourierTransform(long[] input) {
        long[] output = new long[SIZE];
        long wPower = 1;
        for (int i = 0; i < SIZE; i++) {
            long x = 1;
            for (int j = 0; j < input.length; j++) {
                output[i] = (output[i] + input[j] * x) % MOD;
                x = x * wPower % MOD;
            }
            wPower = wPower * ROOT % MOD;
        }
        return output;
    }

    long[] raiseToExponent(long[] arr, int exponent) {
        for (int i = 0; i < arr.length; i++) {
            arr[i] = fastExponentiate(arr[i], exponent);
        }
        return arr;
    }

    long fastExponentiate(long base, int exp) {
        if (exp == 0) return 1;
        if ((exp & 1) == 1) return fastExponentiate(base, exp - 1) * base % MOD;
        long half = fastExponentiate(base, exp >> 1);
        return half * half % MOD;
    }

    void run() {
        int n = readInt();
        int k = readInt();
        long[] poly = new long[10];
        for (int i = 0; i < k; i++) {
            poly[readInt()] = 1;
        }
        long[] transformed = directFourierTransform(poly);
        transformed = raiseToExponent(transformed, n / 2);
        CoefficientArray buffer = new CoefficientArray(transformed);
        transformed = buffer.transform(false);
        for (int i = 0; i < transformed.length; i++) {
            transformed[i] = transformed[i] * SIZE_INVERSE % MOD;
        }
        long answer = 0;
        for (long val : transformed) {
            answer = (answer + val * val) % MOD;
        }
        consoleOutput.println(answer);
    }

    void setup() {
        try {
            if (isConsoleMode) {
                consoleInput = new BufferedReader(new InputStreamReader(System.in));
                consoleOutput = new PrintWriter(System.out);
            } else {
                consoleInput = new BufferedReader(new FileReader("input.txt"));
                consoleOutput = new PrintWriter("output.txt");
            }
            run();
            consoleOutput.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    int readInt() {
        return Integer.parseInt(nextToken());
    }

    String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(consoleInput.readLine());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return tokenizer.nextToken();
    }

    StringTokenizer tokenizer;

    public static void main(String[] args) {
        new FFT().setup();
    }
}
